<template><article class="analytics-metric" :class="{open}" tabindex="0" role="button" :aria-expanded="open" @click="open=!open" @keydown.enter.prevent="open=!open" @keydown.space.prevent="open=!open"><header><h2>{{ metric.title }}</h2><CreatorAnalyticsInfoPopover :text="metric.info" @click.stop /></header><strong>{{ metric.value }} <small v-if="metric.suffix">{{ metric.suffix }}</small></strong><p>{{ metric.change }}</p><div v-if="open" class="analytics-metric__detail">{{ metric.detail }}</div><span>{{ open ? 'Hide detail' : 'View detail' }} →</span></article></template>
<script setup>import{ref}from'vue';import CreatorAnalyticsInfoPopover from './CreatorAnalyticsInfoPopover.vue';defineProps({metric:{type:Object,required:true}});const open=ref(false)</script>
